Q: How to use JavaScript to see if a URL&#39;s resource exists? A: <p><strong>Solution 1:</strong><br />
You can add check like this which will be faster as it does not download full file data.</p>
<pre><code>async function checkUrlExists(url) {
    try {
        const response = await fetch(url, { method: 'HEAD' }); // HEAD avoids downloading the full file
        return response.ok; // Returns true for 200-299 status codes
    } catch (error) {
        return false; // Network error or URL does not exist
    }
}

// Usage
checkUrlExists('https://example.com').then(exists =&gt; {
    console.log(exists ? &quot;Exists!&quot; : &quot;Does not exist.&quot;);
});
</code></pre>
<hr />
<p>OR</p>
<hr />
<p><strong>Solution 2:</strong><br />
You can directly check after the response of it.</p>
<pre><code>function loadElement(elementID) {
    // 1. Define your paths
    const defaultAsset = &quot;/assets/main/&quot; + elementID + &quot;.html&quot;;
    const docURL = document.URL;
    const lastSlash = docURL.lastIndexOf(&quot;/&quot;) + 1;
    const docDir = docURL.substring(0, lastSlash);
    const pathURL = docDir + elementID + &quot;.html&quot;;

    // 2. Attempt to fetch the local file first
    fetch(pathURL)
        .then(response =&gt; {
            // Check if the file exists (status 200-299)
            if (response.ok) {
                return response.text();
            }
            // If not found, fetch the default asset instead
            console.log(`${elementID} not found at ${pathURL}, loading default.`);
            return fetch(defaultAsset).then(defaultRes =&gt; defaultRes.text());
        })
        .then(htmlContent =&gt; {
            document.getElementById(elementID).innerHTML = htmlContent;
        })
        .catch(error =&gt; {
            console.error(`Error loading ${elementID}:`, error);
        });
}
</code></pre>
<p>Which solution to use is totally dependent upon you. If your html files are small in size, i would suggest you go with 2nd solution.</p>

Q: How to check if a function is a constructor A: <p>In the old days you just had to test for functions with a prototype property:</p>
<pre><code>typeof value=='function' &amp;&amp; 'prototype' in value// function with prototype property
</code></pre>
<p>But those were the days before bound and generator functions. For example the above will return <code>false</code> for constructors created with <code>Function.prototype.bind()</code> (new in ES5) and <code>true</code> for generator functions (which can't construct per the ES7 spec).</p>
<p>So these days there are better ways, like this cross-browser solution that also works with bound and generator functions. Acknowledgement to Ryan Hanekamp for his answer which I incorporated in my answer below. This works in both modern and old ES3+ browsers including Node.js and IE:</p>
<pre><code>var isConstructor = typeof Proxy=='function'?
function(value) {// Works in modern environments that support Proxy (ES6+)
    'use strict';
    if (typeof value=='function') {// True of most constructors in modern JS
        try {// Throws if `value` has no [[Construct]] internal method
            var success = new new Proxy(value, {construct:Object});
        }
        catch(e) {
        }
    }
    return !!success;
}:
function(value) {// Pre-ES6 JS. Tested in IE 6 thru 11 and old Safari
    'use strict';

    // Most constructors are functions (with a prototype property)
    // Also true for generators since they construct in pre-ES7 JS
    var is_function = typeof value=='function';// function or generator

    var has_proto_prop = is_function &amp;&amp; 'prototype' in value;

    // If the function has a prototype property and is not a built-in
    // function starting with lowercase, it is probably a constructor.
    // RegExp needed since in IE: !!alert.prototype// true for host functions
    var success = has_proto_prop &amp;&amp;
        !/^\s*\w+ [a-z_]\w*\(\) {\s*\[native c/.test(value);

    var is_ES5 = '1'[0];// Needed to avoid `instanceof` throwing in IE6

    // No prototype property means function might be a bound constructor
    // Host objects can be constructors too such as Image() and Option()
    // and doesn't only apply to objects where typeof value=='function'
    // but also 'object' (host) or 'undefined' (ActiveXObject in IE 11)
    if (is_function? !has_proto_prop &amp;&amp; is_ES5: value===Object(value)) {
        try {
            // instanceof can be used to test for constructors because it
            // throws when used on functions with no prototype property.
            // With bound functions it uses prototype property of target.
            // Since instanceof check throws in old browsers, use `new`
            success = is_ES5? {} instanceof value || 1: new value;
        }
        catch(e) {
        }
    }
    return !!success;
}
isConstructor(window)//false
isConstructor(alert)//false
isConstructor(XMLHttpRequest)//true
isConstructor(Array.bind())//true
isConstructor(function myFunc(){})//true
isConstructor(function* myGenerator(){})//false
// Caveat: IE returns false-positives on bound host objects
isConstructor(isNaN.bind())//false (works in IE since isNaN isn't a host object)
isConstructor(alert.bind())//false (however in IE this returns true (false-positive))
</code></pre>
